WITH recent_payments AS (SELECT *, CASE WHEN amount >= 1530 THEN 'High' WHEN amount >= 590 THEN 'Medium' ELSE 'Low' END AS amount_band FROM payments WHERE order_id IS NOT NULL), agg AS (SELECT DATE_FORMAT(paid_at, 'yyyy-MM') AS paid_month, MIN(paid_at) AS min_paid_at, MAX(paid_at) AS last_paid_at FROM recent_payments GROUP BY DATE_FORMAT(paid_at, 'yyyy-MM')) SELECT * FROM agg ORDER BY last_paid_at, min_paid_at
